import React from 'react';
import ReactDOM from 'react-dom';
import { DatePicker2 } from '@alifd/next';
import dayjs from 'dayjs';

const defaultTimeValue = dayjs('09:00:00', 'HH:mm:ss', true);

function App() {
  return (
    <div style={{ padding: 20 }}>
      {/* DatePicker2 with showTime and timePanelProps.defaultValue */}
      <DatePicker2
        showTime
        // defaultValue for the date portion of the picker:
        defaultValue={dayjs('2021-07-21', 'YYYY-MM-DD')}
        // pass a dayjs time object to the time panel
        timePanelProps={{
          defaultValue: defaultTimeValue,
          format: 'HH:mm:ss'
        }}
        onOk={(val) => console.log('onOk:', val.format('YYYY-MM-DD HH:mm:ss'))}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
